FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL := FALSE;
    motorDown  : BOOL := FALSE;
    errorFlag  : BOOL := FALSE;
END_VAR
VAR
    curState      : INT := 0;
    prevOpenBtn   : BOOL := FALSE;
    prevCloseBtn  : BOOL := FALSE;
    openBtnRise   : BOOL := FALSE;
    closeBtnRise  : BOOL := FALSE;
END_VAR

// 检测边沿
openBtnRise  := openBtn AND NOT prevOpenBtn;
closeBtnRise := closeBtn AND NOT prevCloseBtn;

// 状态机
CASE curState OF
    3: // FAULT
        IF openBtn AND closeBtn THEN
            curState   := 0;
            errorFlag  := FALSE;
            openBtnRise  := FALSE;
            closeBtnRise := FALSE;
        END_IF

    1: // OPENING
        IF obstacle THEN
            curState  := 3;
            errorFlag := TRUE;
            motorUp   := FALSE;
        ELSIF openLimit THEN
            curState  := 0;
            motorUp   := FALSE;
        END_IF

    2: // CLOSING
        IF obstacle THEN
            curState  := 1;
            motorDown := FALSE;
            motorUp   := TRUE;
        ELSIF closeLimit THEN
            curState   := 0;
            motorDown  := FALSE;
        END_IF

    0: // IDLE
        IF openBtnRise AND NOT openLimit THEN
            curState  := 1;
            motorUp   := TRUE;
            motorDown := FALSE;
        ELSIF closeBtnRise AND NOT closeLimit THEN
            curState  := 2;
            motorDown := TRUE;
            motorUp   := FALSE;
        END_IF;
END_CASE

// 清除边沿标志
openBtnRise  := FALSE;
closeBtnRise := FALSE;

// 更新历史
prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;
END_FUNCTION_BLOCK
